def get_platform_info(**_extra):
    import json, os, datetime, time, platform, uuid, subprocess

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    start = time.time()

    # Validation: no parameters supported
    if _extra:
        latency_ms = int((time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "Unsupported parameters provided.", unsupported=list(_extra.keys()), latency_ms=latency_ms)

    # No explicit auth parameter; ambient auth. Choose working context: always allow.
    # Observable service dynamics: no request-log collection defined in schema; nothing to write.

    try:
        hostname = platform.node() or None
        os_name = (platform.system() or "").lower() or "unknown"
        # Normalize to examples where possible
        if os_name.startswith("darwin"):
            os_name = "darwin"
        elif os_name.startswith("linux"):
            os_name = "linux"
        elif os_name.startswith("windows"):
            os_name = "windows"

        os_version = platform.version() or None
        arch = platform.machine() or None

        shell = os.environ.get("SHELL")
        if not shell and os.name == "nt":
            shell = os.environ.get("COMSPEC")
        default_shell = shell or ("powershell" if os.name == "nt" else "/bin/sh")

        shell_version = None
        # Best-effort shell version probing
        try:
            if default_shell and isinstance(default_shell, str):
                base = os.path.basename(default_shell).lower()
                if os.name != "nt":
                    if base in ("bash", "zsh", "sh", "dash", "ksh", "fish"):
                        # Many shells support --version, but not all; best-effort.
                        p = subprocess.run([default_shell, "--version"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=1)
                        out = (p.stdout or p.stderr or "").strip()
                        shell_version = out.splitlines()[0][:256] if out else None
                else:
                    # On Windows, attempt PowerShell version
                    if "powershell" in base or default_shell.lower().endswith("powershell.exe"):
                        p = subprocess.run([default_shell, "-NoProfile", "-Command", "$PSVersionTable.PSVersion.ToString()"],
                                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=2)
                        out = (p.stdout or "").strip()
                        shell_version = out[:256] if out else None
        except Exception:
            shell_version = None

        platform_rows = _load("platform_instances.json")
        now = _now_iso()

        active = None
        for r in platform_rows:
            if isinstance(r, dict) and r.get("status") == "active":
                active = r
                break

        if active is None:
            new_row = {
                "id": _gen_id("pi"),
                "hostname": hostname,
                "os_name": os_name,
                "os_version": os_version,
                "arch": arch,
                "default_shell": default_shell,
                "shell_version": shell_version,
                "status": "active",
                "last_seen_at": now,
                "created_at": now,
                "updated_at": now,
            }
            platform_rows.append(new_row)
            _save("platform_instances.json", platform_rows)
            latency_ms = int((time.time() - start) * 1000)
            return {"platform": new_row, "latency_ms": latency_ms}

        # Update active row fields + last_seen_at
        active["hostname"] = hostname
        active["os_name"] = os_name
        active["os_version"] = os_version
        active["arch"] = arch
        active["default_shell"] = default_shell
        active["shell_version"] = shell_version
        active["last_seen_at"] = now

        # Constraint: last_seen_at >= created_at
        ca = _parse_dt(active.get("created_at"))
        la = _parse_dt(active.get("last_seen_at"))
        if ca and la and la < ca:
            active["last_seen_at"] = active.get("created_at")

        active["updated_at"] = now
        _save("platform_instances.json", platform_rows)

        latency_ms = int((time.time() - start) * 1000)
        return {"platform": active, "latency_ms": latency_ms}
    except Exception as e:
        latency_ms = int((time.time() - start) * 1000)
        return _err("VALIDATION_ERROR", "Unable to resolve platform info.", detail=str(e), latency_ms=latency_ms)

def get_whitelist(status=None, securityLevel=None, query=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    start = time.time()

    if _extra:
        return _err("VALIDATION_ERROR", "Unsupported parameters provided.", unsupported=list(_extra.keys()))

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=["active", "deleted"])
    if securityLevel is not None:
        if not isinstance(securityLevel, str) or securityLevel not in ("safe", "requires_approval", "forbidden"):
            return _err("VALIDATION_ERROR", "Invalid securityLevel filter.", allowed=["safe", "requires_approval", "forbidden"])
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.")
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit out of range.", minimum=1, maximum=200)
        limit_v = limit
    if sortBy is None:
        sort_by = "created_at"
    else:
        if not isinstance(sortBy, str) or sortBy not in ("created_at", "updated_at", "command", "security_level"):
            return _err("VALIDATION_ERROR", "Invalid sortBy.", allowed=["created_at", "updated_at", "command", "security_level"])
        sort_by = sortBy
    if sortOrder is None:
        sort_order = "asc"
    else:
        if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "Invalid sortOrder.", allowed=["asc", "desc"])
        sort_order = sortOrder

    off = _parse_cursor(cursor)
    if off is None:
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = _load("whitelist_commands.json")
    if not isinstance(rows, list):
        rows = []

    # Filter
    out = []
    q = query.lower().strip() if isinstance(query, str) and query.strip() else None
    for r in rows:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if securityLevel is not None and r.get("security_level") != securityLevel:
            continue
        if q:
            hay = " ".join([
                str(r.get("command") or ""),
                str(r.get("normalized_command") or ""),
                str(r.get("description") or ""),
            ]).lower()
            if q not in hay:
                continue
        out.append(r)

    # Sort
    reverse = (sort_order == "desc")

    def _key(r):
        v = r.get(sort_by)
        if v is None:
            return ""
        return v

    out.sort(key=_key, reverse=reverse)

    total = len(out)
    page = out[off:off + limit_v]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    latency_ms = int((time.time() - start) * 1000)
    return {
        "commands": page,
        "pagination": {"total": total, "limit": limit_v, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor},
        "latency_ms": latency_ms,
    }

def add_to_whitelist(command, securityLevel, description=None, **_extra):
    import json, os, datetime, time, uuid, shlex

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _normalize_command(cmd):
        if not isinstance(cmd, str):
            return None
        c = cmd.strip()
        if not c:
            return ""
        try:
            parts = shlex.split(c, posix=(os.name != "nt"))
            if parts:
                c = parts[0]
        except Exception:
            c = c.split()[0]
        return c.strip().lower()

    start = time.time()

    if _extra:
        return _err("VALIDATION_ERROR", "Unsupported parameters provided.", unsupported=list(_extra.keys()))

    if not isinstance(command, str):
        return _err("VALIDATION_ERROR", "command must be a string.")
    cmd_raw = command.strip()
    if len(cmd_raw) < 1 or len(cmd_raw) > 256:
        return _err("VALIDATION_ERROR", "command length out of range.", minimum=1, maximum=256)
    if not isinstance(securityLevel, str) or securityLevel not in ("safe", "requires_approval", "forbidden"):
        return _err("VALIDATION_ERROR", "Invalid securityLevel.", allowed=["safe", "requires_approval", "forbidden"])
    if description is not None:
        if not isinstance(description, str):
            return _err("VALIDATION_ERROR", "description must be a string.")
        if len(description) > 2048:
            return _err("VALIDATION_ERROR", "description too long.", maximum=2048)

    norm = _normalize_command(cmd_raw)
    if norm is None or not norm:
        return _err("VALIDATION_ERROR", "Unable to normalize command.")

    rows = _load("whitelist_commands.json")
    if not isinstance(rows, list):
        rows = []

    now = _now_iso()

    # Upsert by normalized_command where an active row exists: update it
    for r in rows:
        if isinstance(r, dict) and r.get("status") == "active" and r.get("normalized_command") == norm:
            r["command"] = cmd_raw
            r["security_level"] = securityLevel
            r["description"] = description
            r["deleted_at"] = None
            r["updated_at"] = now
            _save("whitelist_commands.json", rows)
            latency_ms = int((time.time() - start) * 1000)
            return {"command": r, "upserted": True, "latency_ms": latency_ms}

    # Insert new active row
    new_row = {
        "id": _gen_id("wc"),
        "command": cmd_raw,
        "normalized_command": norm,
        "security_level": securityLevel,
        "description": description,
        "status": "active",
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    rows.append(new_row)
    _save("whitelist_commands.json", rows)
    latency_ms = int((time.time() - start) * 1000)
    return {"command": new_row, "upserted": False, "latency_ms": latency_ms}

def update_security_level(command, securityLevel, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Rate limit / quota: none declared in schema; still log every call.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status, error_code=None):
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "update_security_level",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    try:
        if not isinstance(command, str) or not (1 <= len(command.strip()) <= 256):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "command must be a non-empty string of length 1..256")
        if not isinstance(securityLevel, str) or securityLevel not in ("safe", "requires_approval", "forbidden"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "securityLevel must be one of: safe, requires_approval, forbidden")

        normalized = command.strip()
        # server normalization: trim; lower-case for key stability
        normalized_key = normalized.lower()

        wl = _load("whitelist_commands.json")
        if not isinstance(wl, list):
            wl = []

        target = None
        for row in wl:
            if isinstance(row, dict) and row.get("status") == "active" and row.get("normalized_command") == normalized_key:
                target = row
                break

        if not target:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Active whitelisted command not found for given command")

        # Update
        target["security_level"] = securityLevel
        target["updated_at"] = now

        # Enforce constraints: deleted_at must be null for active
        target["deleted_at"] = None

        _save("whitelist_commands.json", wl)

        _log("ok")
        return {"data": target}
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def remove_from_whitelist(command, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status, error_code=None):
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "remove_from_whitelist",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    try:
        if not isinstance(command, str) or not (1 <= len(command.strip()) <= 256):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "command must be a non-empty string of length 1..256")

        normalized = command.strip()
        normalized_key = normalized.lower()

        wl = _load("whitelist_commands.json")
        if not isinstance(wl, list):
            wl = []

        target = None
        for row in wl:
            if isinstance(row, dict) and row.get("normalized_command") == normalized_key:
                # must exist and be active to remove
                if row.get("status") == "active":
                    target = row
                break

        if not target:
            # If exists but deleted, also NOT_FOUND per tool description
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Whitelisted command not found or already deleted")

        # Lifecycle transition active -> deleted only
        if target.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Command cannot be removed from current state", current_status=target.get("status"))

        target["status"] = "deleted"
        target["deleted_at"] = now
        target["updated_at"] = now

        _save("whitelist_commands.json", wl)

        _log("ok")
        return {"data": target}
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def get_pending_commands(status=None, whitelistCommandId=None, reviewedBy=None, requestedAfter=None, requestedBefore=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status_s, error_code=None, extra=None):
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get_pending_commands",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        }
        if isinstance(extra, dict):
            entry.update(extra)
        logs.append(entry)
        _save("request_logs.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            raise ValueError(f"{field} must be a valid RFC3339/ISO-8601 date-time")

    def _dt_from_row(v):
        if v is None or not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _cursor_to_offset(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            raise ValueError("cursor must be a string")
        cur = cur.strip()
        if cur == "":
            return 0
        # Accept vendor opaque cursor formats, but also accept simple integer offsets
        if cur.isdigit():
            return int(cur)
        # If cursor is an id, use it as a position marker after sorting
        return cur

    # ---- validate inputs (relaxed to match observed calls; only enforce types/enums/ranges/date ranges) ----
    allowed_status = {"pending", "approved", "denied", "expired", "cancelled"}
    if status is not None and status not in allowed_status:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of pending, approved, denied, expired, cancelled")

    if whitelistCommandId is not None and not isinstance(whitelistCommandId, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "whitelistCommandId must be a string")
    # Do NOT enforce strict id pattern here: datastore contains ssh_cmd_01J... ids; accept any string.

    if reviewedBy is not None and not isinstance(reviewedBy, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reviewedBy must be a string")

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_n = limit

    allowed_sort_by = {"requested_at", "reviewed_at", "expires_at", "created_at", "updated_at", "status"}
    if sortBy is None:
        sort_by = "requested_at"
    else:
        if sortBy not in allowed_sort_by:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sortBy is invalid")
        sort_by = sortBy

    if sortOrder is None:
        sort_order = "desc"
    else:
        if sortOrder not in {"asc", "desc"}:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sortOrder must be asc or desc")
        sort_order = sortOrder

    try:
        after_dt = _parse_dt(requestedAfter, "requestedAfter")
        before_dt = _parse_dt(requestedBefore, "requestedBefore")
    except ValueError as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))

    if after_dt is not None and before_dt is not None and after_dt > before_dt:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "requestedAfter must be <= requestedBefore")

    try:
        cur_marker = _cursor_to_offset(cursor)
    except ValueError as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))

    approvals = _load("approval_requests.json")
    if not isinstance(approvals, list):
        approvals = []

    # ---- auto-expire pending requests whose expires_at <= now ----
    changed = False
    for r in approvals:
        if not isinstance(r, dict):
            continue
        if r.get("status") == "pending":
            exp_dt = _dt_from_row(r.get("expires_at"))
            if exp_dt is not None and exp_dt <= now_dt:
                r["status"] = "expired"
                r["reviewed_at"] = now_iso
                if not r.get("reviewed_by"):
                    r["reviewed_by"] = "system:expiry-sweeper"
                r["updated_at"] = now_iso
                changed = True
    if changed:
        _save("approval_requests.json", approvals)

    # ---- filter ----
    rows = []
    for r in approvals:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if whitelistCommandId is not None and r.get("whitelist_command_id") != whitelistCommandId:
            continue
        if reviewedBy is not None and r.get("reviewed_by") != reviewedBy:
            continue
        req_dt = _dt_from_row(r.get("requested_at"))
        if after_dt is not None and (req_dt is None or req_dt < after_dt):
            continue
        if before_dt is not None and (req_dt is None or req_dt > before_dt):
            continue
        rows.append(r)

    # ---- sort ----
    def _sort_key(r):
        if sort_by == "status":
            return (str(r.get("status") or ""), str(r.get("id") or ""))
        dt = _dt_from_row(r.get(sort_by))
        # None sorts last in asc, first in desc by using sentinel
        if dt is None:
            sentinel = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if sort_order == "desc" else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            dt = sentinel
        return (dt, str(r.get("id") or ""))

    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)

    # ---- paginate ----
    start = 0
    next_cursor = None
    if isinstance(cur_marker, int):
        start = max(0, min(cur_marker, total))
    else:
        # treat marker as "last seen id": start after that id
        marker_id = cur_marker
        if marker_id:
            for i, r in enumerate(rows):
                if r.get("id") == marker_id:
                    start = i + 1
                    break

    page = rows[start:start + limit_n]
    if start + limit_n < total and len(page) > 0:
        # opaque enough: return last id as cursor
        next_cursor = str(page[-1].get("id") or (start + limit_n))

    _log("ok")
    return {
        "approval_requests": page,
        "page": {
            "total": total,
            "limit": limit_n,
            "has_more": (start + limit_n) < total,
            "next_cursor": next_cursor
        }
    }

def approve_command(commandId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_s, error_code=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "approve_command",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        })
        _save("request_logs.json", logs)

    def _sweep_expired(approvals):
        changed = False
        for r in approvals:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "pending":
                continue
            exp_dt = _parse_dt(r.get("expires_at"))
            if exp_dt is not None and exp_dt <= now_dt:
                r["status"] = "expired"
                r["reviewed_at"] = now_iso
                r["reviewed_by"] = r.get("reviewed_by") or "system:expiry-sweeper"
                r["updated_at"] = now_iso
                changed = True
        return changed

    try:
        if not isinstance(commandId, str) or not commandId.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "commandId must be a non-empty string", field="commandId")

        approvals = _ensure_list(_load("approval_requests.json"))
        changed_by_sweep = _sweep_expired(approvals)
        if changed_by_sweep:
            _save("approval_requests.json", approvals)

        req = None
        for r in approvals:
            if isinstance(r, dict) and r.get("id") == commandId:
                req = r
                break

        # Compatibility behavior: some callers mistakenly pass a platform instance id; interpret as
        # "approve the latest pending request for this platform" if unambiguous.
        if req is None and isinstance(commandId, str) and commandId.startswith("ssh_inst_"):
            executions = _ensure_list(_load("command_executions.json"))
            latest_req_id = None
            latest_ts = None
            for ex in executions:
                if not isinstance(ex, dict):
                    continue
                if ex.get("platform_instance_id") != commandId:
                    continue
                arid = ex.get("approval_request_id")
                if not isinstance(arid, str) or not arid:
                    continue
                # consider only pending requests
                for r in approvals:
                    if isinstance(r, dict) and r.get("id") == arid and r.get("status") == "pending":
                        ts = _parse_dt(r.get("requested_at")) or _parse_dt(r.get("created_at")) or now_dt
                        if latest_ts is None or ts > latest_ts:
                            latest_ts = ts
                            latest_req_id = arid
                        break
            if latest_req_id:
                for r in approvals:
                    if isinstance(r, dict) and r.get("id") == latest_req_id:
                        req = r
                        commandId = latest_req_id
                        break

        if req is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Approval request not found", id=commandId)

        # enforce expiry at time of approve
        exp_dt = _parse_dt(req.get("expires_at"))
        if req.get("status") == "pending" and exp_dt is not None and exp_dt <= now_dt:
            req["status"] = "expired"
            req["reviewed_at"] = now_iso
            req["reviewed_by"] = req.get("reviewed_by") or "system:expiry-sweeper"
            req["updated_at"] = now_iso
            _save("approval_requests.json", approvals)
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Approval request is expired and cannot be approved", id=commandId, status="expired")

        if req.get("status") != "pending":
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Approval request is not pending and cannot be approved", id=commandId, status=req.get("status"))

        # transition pending -> approved
        req["status"] = "approved"
        req["reviewed_at"] = now_iso
        req["reviewed_by"] = req.get("reviewed_by") or "user:approver"
        req["updated_at"] = now_iso
        if "created_at" not in req or not req.get("created_at"):
            req["created_at"] = now_iso
        if "requested_at" not in req or not req.get("requested_at"):
            req["requested_at"] = now_iso

        _save("approval_requests.json", approvals)
        _log("ok", None)
        return {"approval_request": req}
    except (TypeError, ValueError) as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

