def get_command_execution(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _log(status_s, error_code=None):
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get_command_execution",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(id, str) or not id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        exec_id = id.strip()

        executions = _load("command_executions.json")
        if not isinstance(executions, list):
            executions = []

        row = None
        for r in executions:
            if isinstance(r, dict) and r.get("id") == exec_id:
                row = r
                break

        if row is None:
            # Compatibility: some clients mistakenly pass a platform_instance_id; return the most recent execution for that instance.
            fallback = None
            for r in executions:
                if isinstance(r, dict) and r.get("platform_instance_id") == exec_id:
                    if fallback is None:
                        fallback = r
                    else:
                        ca = r.get("created_at")
                        cb = fallback.get("created_at")
                        if isinstance(ca, str) and isinstance(cb, str) and ca > cb:
                            fallback = r
            if fallback is not None:
                _log("ok")
                return {"command_execution": fallback}

            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Command execution not found", id=exec_id)

        _log("ok")
        return {"command_execution": row}
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error while fetching command execution", detail=str(e))

def get_command_executions(platformInstanceId=None, whitelistCommandId=None, approvalRequestId=None, policyDecision=None, status=None, startedAfter=None, startedBefore=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_from_row(row, field):
        v = row.get(field)
        if v is None:
            return None
        return _parse_dt(v) if isinstance(v, str) else None

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return "bad"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "bad"
            if "v" not in obj or obj.get("v") != 1:
                return "bad"
            if "sort_by" not in obj or "sort_order" not in obj or "last_id" not in obj or "last_val" not in obj:
                return "bad"
            return obj
        except Exception:
            return "bad"

    def _encode_cursor(sort_by, sort_order, last_val, last_id):
        obj = {"v": 1, "sort_by": sort_by, "sort_order": sort_order, "last_val": last_val, "last_id": last_id}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- validate filters ----
    if platformInstanceId is not None and (not isinstance(platformInstanceId, str) or not platformInstanceId.strip()):
        return _err("VALIDATION_ERROR", "platformInstanceId must be a non-empty string when provided")
    if whitelistCommandId is not None and (not isinstance(whitelistCommandId, str) or not whitelistCommandId.strip()):
        return _err("VALIDATION_ERROR", "whitelistCommandId must be a non-empty string when provided")
    if approvalRequestId is not None and (not isinstance(approvalRequestId, str) or not approvalRequestId.strip()):
        return _err("VALIDATION_ERROR", "approvalRequestId must be a non-empty string when provided")

    allowed_policy = {"allowed", "pending_approval", "blocked_not_whitelisted", "blocked_forbidden", "blocked_denied"}
    if policyDecision is not None:
        if not isinstance(policyDecision, str) or policyDecision not in allowed_policy:
            return _err("VALIDATION_ERROR", "policyDecision is invalid", allowed=sorted(list(allowed_policy)))

    allowed_status = {"queued", "running", "succeeded", "failed", "blocked"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status is invalid", allowed=sorted(list(allowed_status)))

    s_after = _parse_dt(startedAfter) if startedAfter is not None else None
    s_before = _parse_dt(startedBefore) if startedBefore is not None else None
    c_after = _parse_dt(createdAfter) if createdAfter is not None else None
    c_before = _parse_dt(createdBefore) if createdBefore is not None else None

    if startedAfter is not None and s_after is None:
        return _err("VALIDATION_ERROR", "startedAfter must be an RFC3339 date-time string")
    if startedBefore is not None and s_before is None:
        return _err("VALIDATION_ERROR", "startedBefore must be an RFC3339 date-time string")
    if createdAfter is not None and c_after is None:
        return _err("VALIDATION_ERROR", "createdAfter must be an RFC3339 date-time string")
    if createdBefore is not None and c_before is None:
        return _err("VALIDATION_ERROR", "createdBefore must be an RFC3339 date-time string")

    if s_after and s_before and s_after > s_before:
        return _err("VALIDATION_ERROR", "startedAfter must be <= startedBefore")
    if c_after and c_before and c_after > c_before:
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if sortBy is None:
        sortBy = "created_at"
    if sortOrder is None:
        sortOrder = "desc"
    allowed_sort_by = {"created_at", "started_at", "finished_at", "duration_ms", "status"}
    if sortBy not in allowed_sort_by:
        return _err("VALIDATION_ERROR", "sortBy is invalid", allowed=sorted(list(allowed_sort_by)))
    if sortOrder not in {"asc", "desc"}:
        return _err("VALIDATION_ERROR", "sortOrder is invalid", allowed=["asc", "desc"])

    cur = _decode_cursor(cursor)
    if cur == "bad":
        return _err("VALIDATION_ERROR", "cursor is invalid")
    if isinstance(cur, dict):
        # cursor must match current sort parameters
        if cur.get("sort_by") != sortBy or cur.get("sort_order") != sortOrder:
            return _err("VALIDATION_ERROR", "cursor sort does not match requested sortBy/sortOrder")

    rows = _load("command_executions.json")

    # ---- filter ----
    out = []
    for r in rows:
        if platformInstanceId is not None and r.get("platform_instance_id") != platformInstanceId:
            continue
        if whitelistCommandId is not None and r.get("whitelist_command_id") != whitelistCommandId:
            continue
        if approvalRequestId is not None and r.get("approval_request_id") != approvalRequestId:
            continue
        if policyDecision is not None and r.get("policy_decision") != policyDecision:
            continue
        if status is not None and r.get("status") != status:
            continue

        if s_after is not None or s_before is not None:
            dt = _dt_from_row(r, "started_at")
            # if started_at is null, exclude when filtering by started time bounds
            if dt is None:
                continue
            if s_after is not None and dt < s_after:
                continue
            if s_before is not None and dt > s_before:
                continue

        if c_after is not None or c_before is not None:
            dtc = _dt_from_row(r, "created_at")
            if dtc is None:
                continue
            if c_after is not None and dtc < c_after:
                continue
            if c_before is not None and dtc > c_before:
                continue

        out.append(r)

    total = len(out)

    # ---- sort ----
    def _sort_key(r):
        v = r.get(sortBy)
        if sortBy in {"created_at", "started_at", "finished_at"}:
            dt = _parse_dt(v) if isinstance(v, str) else None
            # None sorts last in asc, first in desc handled by tuple
            return (dt is None, dt, r.get("id"))
        if sortBy == "duration_ms":
            dv = v if isinstance(v, int) else None
            return (dv is None, dv, r.get("id"))
        if sortBy == "status":
            sv = v if isinstance(v, str) else ""
            return (False, sv, r.get("id"))
        return (False, str(v), r.get("id"))

    reverse = (sortOrder == "desc")
    out.sort(key=_sort_key, reverse=reverse)

    # ---- apply cursor ----
    if isinstance(cur, dict):
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        # move past the last seen item: find the first index strictly after cursor position
        def _cursor_cmp(r):
            rid = r.get("id")
            rv = r.get(sortBy)
            # normalize comparable values
            if sortBy in {"created_at", "started_at", "finished_at"}:
                rv_dt = _parse_dt(rv) if isinstance(rv, str) else None
                lv_dt = _parse_dt(last_val) if isinstance(last_val, str) else None
                return rv_dt, lv_dt, rid
            return rv, last_val, rid

        start_idx = 0
        found_boundary = False
        for i, r in enumerate(out):
            rv, lv, rid = _cursor_cmp(r)
            if sortOrder == "asc":
                if rv is None and lv is not None:
                    continue
                if rv is not None and lv is None:
                    # cursor had None, everything with value is after
                    start_idx = i
                    found_boundary = True
                    break
                if rv == lv and rid == last_id:
                    start_idx = i + 1
                    found_boundary = True
                    break
            else:
                # desc
                if rv is None and lv is not None:
                    # None comes first in desc in our sort tuple; treat as before/at cursor appropriately
                    pass
                if rv == lv and rid == last_id:
                    start_idx = i + 1
                    found_boundary = True
                    break
        if not found_boundary and total > 0:
            # If cursor doesn't correspond to any element in current filtered set, it's invalid
            return _err("VALIDATION_ERROR", "cursor does not match the current result set")
        out = out[start_idx:]

    page = out[:limit]
    has_more = len(out) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(sortBy, sortOrder, last.get(sortBy), last.get("id"))

    return {
        "command_executions": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sortBy,
            "sort_order": sortOrder,
        }
    }

def approve_pending_command(approvalRequestId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0210000" if __import__("os").path.isdir("./environment_mix/0210000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_s, error_code=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "approve_pending_command",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        })
        _save("request_logs.json", logs)

    def _sweep_expired(approvals):
        changed = False
        for r in approvals:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "pending":
                continue
            exp_dt = _parse_dt(r.get("expires_at"))
            if exp_dt is not None and exp_dt <= now_dt:
                r["status"] = "expired"
                r["reviewed_at"] = now_iso
                r["reviewed_by"] = r.get("reviewed_by") or "system:expiry-sweeper"
                r["updated_at"] = now_iso
                changed = True
        return changed

    try:
        if not isinstance(approvalRequestId, str) or not approvalRequestId.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "approvalRequestId must be a non-empty string", field="approvalRequestId")

        approvals = _ensure_list(_load("approval_requests.json"))
        changed_by_sweep = _sweep_expired(approvals)
        if changed_by_sweep:
            _save("approval_requests.json", approvals)

        req = None
        for r in approvals:
            if isinstance(r, dict) and r.get("id") == approvalRequestId:
                req = r
                break
        if req is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Approval request not found", id=approvalRequestId)

        exp_dt = _parse_dt(req.get("expires_at"))
        if req.get("status") == "pending" and exp_dt is not None and exp_dt <= now_dt:
            req["status"] = "expired"
            req["reviewed_at"] = now_iso
            req["reviewed_by"] = req.get("reviewed_by") or "system:expiry-sweeper"
            req["updated_at"] = now_iso
            _save("approval_requests.json", approvals)
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Approval request is expired and cannot be approved", id=approvalRequestId, status="expired")

        if req.get("status") != "pending":
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Approval request is not pending and cannot be approved", id=approvalRequestId, status=req.get("status"))

        req["status"] = "approved"
        req["reviewed_at"] = now_iso
        req["reviewed_by"] = req.get("reviewed_by") or "user:approver"
        req["updated_at"] = now_iso
        if "created_at" not in req or not req.get("created_at"):
            req["created_at"] = now_iso
        if "requested_at" not in req or not req.get("requested_at"):
            req["requested_at"] = now_iso

        _save("approval_requests.json", approvals)
        _log("ok", None)
        return {"approval_request": req}
    except (TypeError, ValueError) as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

